package com.example.billing.service;
import static com.example.billing.domain.BillingConstants.*;import com.example.billing.domain.*;import com.example.billing.persistence.Repositories.*;import java.math.*;import java.time.*;import java.util.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class InvoiceService {public enum Outcome{CREATED,EXISTING,FAILED}public record Result(Outcome outcome,Invoice invoice,String errorCode,String errorMessage){}private final InvoiceRepository invoices;private final SubscriptionRepository subscriptions;private final PricePlanRepository plans;private final ProductRepository products;private final KeyedLock locks;private final Clock clock;public InvoiceService(InvoiceRepository i,SubscriptionRepository s,PricePlanRepository p,ProductRepository products,KeyedLock locks,Clock clock){invoices=i;subscriptions=s;plans=p;this.products=products;this.locks=locks;this.clock=clock;}@Transactional(readOnly=true)public Invoice get(UUID id){return invoices.findById(id).orElse(null);}@Transactional(readOnly=true)public List<Invoice> list(UUID id){return invoices.findByCustomerIdOrderByCreatedAtDescIdDesc(id);}public Result generate(UUID id){var sub=subscriptions.findById(id).filter(x->SubscriptionStatus.ACTIVE.equals(x.status)).orElse(null);if(sub==null)return fail("subscription_not_found","Subscription does not exist or is not active.");var plan=plans.findById(sub.pricePlanId).orElse(null);if(plan==null)return fail("price_plan_not_found","Subscription price plan does not exist.");if(!BillingType.RECURRING.equals(plan.billingType))return fail("billing_type_not_supported","Billing type '"+plan.billingType+"' is not supported for invoice generation.");try(var ignored=locks.acquire("invoice:"+sub.id+":"+sub.currentPeriodStart+":"+sub.currentPeriodEnd)){var old=invoices.findBySubscriptionIdAndBillingPeriodStartAndBillingPeriodEnd(sub.id,sub.currentPeriodStart,sub.currentPeriodEnd).orElse(null);if(old!=null)return new Result(Outcome.EXISTING,old,null,null);var invoice=build(sub,plan);try{invoices.saveAndFlush(invoice);return new Result(Outcome.CREATED,invoice,null,null);}catch(DataIntegrityViolationException e){old=invoices.findBySubscriptionIdAndBillingPeriodStartAndBillingPeriodEnd(sub.id,sub.currentPeriodStart,sub.currentPeriodEnd).orElseThrow(()->e);return new Result(Outcome.EXISTING,old,null,null);}}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException(e);}}private Invoice build(Subscription s,PricePlan p){var x=new Invoice();x.id=UUID.randomUUID();x.customerId=s.customerId;x.subscriptionId=s.id;x.status=InvoiceStatus.OPEN;x.amountDue=p.amount;x.amountPaid=BigDecimal.ZERO;x.billingPeriodStart=s.currentPeriodStart;x.billingPeriodEnd=s.currentPeriodEnd;x.dueDate=s.currentPeriodEnd;x.createdAt=OffsetDateTime.now(clock);var l=new InvoiceLine();l.id=UUID.randomUUID();l.invoice=x;l.description=products.findById(p.productId).map(v->v.name).orElse("Subscription")+(BillingInterval.MONTH.equals(p.billingInterval)?" monthly subscription":BillingInterval.YEAR.equals(p.billingInterval)?" yearly subscription":" subscription");l.quantity=BigDecimal.ONE;l.unitPrice=p.amount;l.amount=p.amount;x.lines.add(l);return x;}private static Result fail(String c,String m){return new Result(Outcome.FAILED,null,c,m);}}
